def reflected(value,length):
    phase=value%(length*2)
    return phase if phase<=length else length*2-phase

def sample_cc0(u,z,seed):
    patch=CC0_PATCHES[int(round(seed*100))%len(CC0_PATCHES)]
    scale=2.25+.5*random_unit(91,seed)
    x=reflected(u/scale+seed*.137,patch['widthMetres'])/patch['widthMetres']*(patch['width']-1)
    y=reflected(z/scale+seed*.219,patch['heightMetres'])/patch['heightMetres']*(patch['height']-1)
    ix=min(patch['width']-2,int(x));iy=min(patch['height']-2,int(y));tx=x-ix;ty=y-iy
    a=patch['samples'][iy][ix];b=patch['samples'][iy][ix+1]
    c=patch['samples'][iy+1][ix];d=patch['samples'][iy+1][ix+1]
    result=[]
    for k in range(3):result.append((a[k]*(1-tx)+b[k]*tx)*(1-ty)+(c[k]*(1-tx)+d[k]*tx)*ty)
    # The source front points toward-Y. Relief is applied only radially, so
    # this detail cannot change the proven vertical column ordering.
    return -result[0]*scale,(result[1],result[2])

def append_butte(points,faces,point_uvs,cap_centers,center,rx,ry,bottom,top,angle,segments,vertical,seed,kind):
    n=Vector((math.cos(angle),math.sin(angle),0));along=Vector((-n.y,n.x,0))
    # A dense temporary plan lookup does not add mesh vertices. Mesh vertices
    # occur at fracture valleys/shoulders and explicit bed transitions only.
    lookup_count=2048;plan_points=[plan(2*math.pi*i/lookup_count,rx,ry) for i in range(lookup_count+1)]
    arc=[0.0]
    for i in range(lookup_count):arc.append(arc[-1]+(plan_points[i+1]-plan_points[i]).length)
    perimeter=arc[-1];joint_count=max(12,round(perimeter/7.0))
    height=top-bottom
    rock_start=max(bottom,-13+7*math.sin(seed)) if kind=='base' else bottom
    large_rear=kind=="base" and top>120
    bed_minimum=13.0 if large_rear else 6.0
    bed_variation=8.0 if large_rear else 5.0
    boundaries=[];level=rock_start+bed_minimum+3*random_unit(6,seed)
    while level<top-3:
        boundaries.append(level);level+=bed_minimum+bed_variation*random_unit(len(boundaries)+12,seed)
    row_z=[bottom,top]
    if rock_start>bottom+2:
        row_z.extend([bottom+(rock_start-bottom)*.32,bottom+(rock_start-bottom)*.67,rock_start])
    for boundary in boundaries:row_z.extend([boundary-.9,boundary+.9])
    row_z=sorted(set(row_z))
    detail_rows=[]
    for lo,hi in zip(row_z,row_z[1:]):
        if not large_rear and lo>=rock_start and hi-lo>3.0:detail_rows.append((lo+hi)*.5)
    row_z=sorted(set(row_z+detail_rows))
    intervals=[4.5+4.5*random_unit(j,seed) for j in range(joint_count)]
    factor=perimeter/sum(intervals);reference_joints=[0.0]
    for interval in intervals:reference_joints.append(reference_joints[-1]+interval*factor)
    joint_sets=[]
    for band in range(len(boundaries)+1):
        positions=[0.0]
        for joint in range(1,joint_count):
            left=reference_joints[joint]-reference_joints[joint-1]
            right=reference_joints[joint+1]-reference_joints[joint]
            shift=.16*min(left,right)*math.sin(band*1.71+joint*2.13+seed)
            positions.append(reference_joints[joint]+shift)
        positions.append(perimeter)
        if any(positions[i+1]<=positions[i] for i in range(joint_count)):
            raise RuntimeError('Joint ordering must remain strictly increasing.')
        joint_sets.append(positions)
    # Height profiles are attached to column identity, not to each row's
    # staggered XY coordinate. Analytically dz/dnominal_z >=
    # 1 - .08*(1.5/.55) - .025*pi > .70 for the bounded terms below.
    column_profiles=[]
    for joint in range(joint_count):
        interval=reference_joints[joint+1]-reference_joints[joint]
        for fraction in [0,.15,.5,.85]:
            u=reference_joints[joint]+interval*fraction
            low=0;high=lookup_count
            while high-low>1:
                middle=(low+high)//2
                if arc[middle]<=u:low=middle
                else:high=middle
            blend=(u-arc[low])/(arc[high]-arc[low]);p=plan_points[low].lerp(plan_points[high],blend)
            broad=noise.noise(Vector((p.x*.035+seed,p.y*.035-seed,seed*.37)))
            top_break=4.3*broad+2.3*noise.noise(Vector((p.x*.12,p.y*.12,seed)))
            bound=min(4.5,height*.08)
            top_break=max(-bound,min(bound,top_break))
            bed_bend=min(1.0,height*.025)*math.sin(u*.055+seed)
            column_profiles.append((top_break,bed_bend))
    surface_records.append({'seed':seed,'kind':kind,'referencePlanPerimeterMetres':perimeter,
        'jointsPerBed':joint_count,'verticesPerRing':joint_count*4,'verticalRings':len(row_z),
        'bedHeightsMetres':boundaries,'rockStartMetres':rock_start,'coarseDistantBase':large_rear,
        'heightProfile':'Stable per-column bounded profile; analytical vertical derivative lower bound greater than0.70.',
        'cc0Patch':int(round(seed*100))%len(CC0_PATCHES),'uniformDetailScale':2.25+.5*random_unit(91,seed),
        'sampling':'Vertices at fractured block shoulders and bed transitions; no uniform dense grid.'})
    rings=[]
    for row,nominal_z in enumerate(row_z):
        t=(nominal_z-bottom)/height;ring=[]
        band=0
        while band<len(boundaries) and nominal_z>boundaries[band]:band+=1
        positions=joint_sets[band]
        for joint in range(joint_count):
            interval=positions[joint+1]-positions[joint]
            for subdivision,fraction in enumerate([0,.15,.5,.85]):
                u=positions[joint]+interval*fraction
                low=0;high=lookup_count
                while high-low>1:
                    middle=(low+high)//2
                    if arc[middle]<=u:low=middle
                    else:high=middle
                blend=(u-arc[low])/(arc[high]-arc[low])
                p=plan_points[low].lerp(plan_points[high],blend)
                theta=2*math.pi*(low+blend)/lookup_count
                broad=noise.noise(Vector((p.x*.035+seed,p.y*.035-seed,seed*.37)))
                medium=noise.noise(Vector((p.x*.11,p.y*.11,seed+nominal_z*.09)))
                # Stable bounded height profile is independent of row XY
                # staggering, fixing the demonstrated04 ring inversion.
                top_break,bed_bend=column_profiles[joint*4+subdivision]
                z=nominal_z+top_break*smooth(.45,1,t)+bed_bend*math.sin(t*math.pi)
                radial=p.normalized()
                if kind=='base':
                    talus_end=rock_start+8*math.sin(theta*2.7+seed)
                    foot=max(0,(talus_end-z)/max(1,talus_end-bottom))
                    lobe=.30+.70*max(0,math.sin(theta*3+seed))**2
                    outward=76*lobe*foot**1.25
                    scale=.77;cliff_weight=smooth(rock_start-4,rock_start+8,z)
                    relief=3.5*noise.noise(Vector((p.x*.045,p.y*.045,z*.05+seed)))
                    relief+=2.0*noise.noise(Vector((p.x*.12,p.y*.12,z*.15+seed)))
                else:
                    outward=7*(1-t)**1.4 if kind=='spur' else 0.0
                    scale=1-.035*t;cliff_weight=1.0
                    relief=2.3*broad+1.15*medium
                terrace=0.0
                for bed,boundary in enumerate(boundaries):
                    termination=noise.noise(Vector((u*.022+bed*2.1,seed,bed*.73)))
                    active=smooth(-.12,.22,termination)
                    terrace+=(.9+1.6*random_unit(bed+35,seed))*active*smooth(boundary-.9,boundary+.9,nominal_z)
                # Joints change position in every bed. A finite valley joins
                # neighbouring angular block faces, rather than a continuous
                # sinusoidal rib repeated from foundation to summit.
                crack=(.18+.32*random_unit(joint+7,seed+band)) if subdivision==0 else 0.0
                block=(random_unit(joint+21,seed+band*1.67)-.5)*.65
                cc0_relief,cc0_uv=sample_cc0(u,z,seed)
                relief+=(block-crack+cc0_relief)*cliff_weight-terrace
                relief=max(relief,-p.length*.55)
                px=p.x*scale+radial.x*(outward+relief)
                py=p.y*scale+radial.y*(outward+relief)
                point=Vector(center)+along*px+n*py;point.z=z
                if rings and point.z<=points[rings[-1][joint*4+subdivision]].z:
                    raise RuntimeError('Authored vertical ring must strictly increase.')
                ring.append(len(points));points.append(point);point_uvs.append(cc0_uv)
        rings.append(ring)
    count=joint_count*4
    for row in range(len(rings)-1):
        for column in range(count):
            nxt=(column+1)%count
            faces.append((rings[row][column],rings[row][nxt],rings[row+1][nxt],rings[row+1][column]))
    bottom_center=len(points);points.append(Vector((center[0],center[1],bottom)));point_uvs.append((0,0));cap_centers.add(bottom_center)
    top_center=len(points);points.append(Vector((center[0],center[1],top-.25)));point_uvs.append((0,0));cap_centers.add(top_center)
    for column in range(count):
        nxt=(column+1)%count
        faces.append((bottom_center,rings[0][nxt],rings[0][column]))
        faces.append((top_center,rings[-1][column],rings[-1][nxt]))

surface_records=[]

def build_terraced_mass(spec,obj):
    index,ax,ay,length,degrees,nominal,bottom,rear,columns,vertical=spec
    seed=index*1.17;angle=math.radians(degrees)
    n=Vector((math.cos(angle),math.sin(angle),0));along=Vector((-n.y,n.x,0));anchor=Vector((ax,ay,0))
    points=[];faces=[];point_uvs=[];cap_centers=set();record_start=len(surface_records)
    base_center=anchor-n*24
    for base_group in range(2):
        center=base_center+along*((base_group-.5)*length*.48)+n*((base_group-.5)*13)
        summit=nominal-36-base_group*4+2*math.sin(seed+base_group)
        append_butte(points,faces,point_uvs,cap_centers,center,length*.39,75 if index<=37 else 68,min(bottom,-82),summit,
                     angle+.18*math.sin(seed+base_group),0,0,seed+base_group*.93,'base')
    count=2+(index%3)
    for group in range(count):
        fraction=(group+.5)/count-.5
        offset=fraction*.78*length
        summit=nominal-3-11*random_unit(group+1,seed)
        rx=length*(.27 if count==2 else .22 if count==3 else .17)
        ry=26+7*random_unit(group+3,seed)
        center=anchor+along*offset-n*(19+24*random_unit(group+8,seed))
        append_butte(points,faces,point_uvs,cap_centers,center,rx,ry,nominal-45,summit,
                     angle+.38*(random_unit(group+12,seed)-.5),0,0,seed+2.1+group*2.7,'upper')
    for group in range(2+(index%2)):
        offset=(group-.6)*length*.22
        center=base_center+n*(54+5*math.sin(seed+group))+along*offset
        append_butte(points,faces,point_uvs,cap_centers,center,14+6*random_unit(group+19,seed),13+4*random_unit(group+20,seed),
                     -39,nominal-50-8*random_unit(group+29,seed),angle+.35*math.sin(seed+group),0,0,seed+9.3+group,'spur')
    for record in surface_records[record_start:]:record["moduleIndex"]=index
    inverse=obj.matrix_world.inverted()
    mesh=bpy.data.meshes.new('Canyon_Far%02d_RearCliffBelt_V19_08_L0'%index)
    mesh.from_pydata([inverse@point for point in points],[],faces);mesh.update()
    mesh.materials.append(material);mesh.materials.append(cap_material)
    layer=mesh.uv_layers.new(name='UV0_CC0Surface')
    for polygon in mesh.polygons:
        polygon.material_index=1 if any(i in cap_centers for i in polygon.vertices) else 0
        for loop in polygon.loop_indices:layer.data[loop].uv=point_uvs[mesh.loops[loop].vertex_index]
